class Solution:
    def findDuplicate(self, nums: List[int]) -> int:
        slow, fast = nums[0], nums[0]
        while True:                  # 至少执行一次, 排除掉一开始相同的情况
            slow = nums[slow]        # x = nums[x]相当于x = x.next, 反正是映射了一次
            fast = nums[nums[fast]]
            if slow == fast:
                break
        slow = nums[0]
        while slow != fast:
            slow = nums[slow]
            fast = nums[fast]
        return slow
